      "path": "src/data.js",
      "language": "javascript",
      "content": "export const mealCatalog = [
  {
    id: "rice-beans",
    name: "Rice and beans",
    ingredients: ["rice", "beans"]
  },
  {
    id: "tomato-pasta",
    name: "Tomato pasta",
    ingredients: ["pasta", "tomato"]
  },
  {
    id: "lentil-stew",
    name: "Lentil stew",
    ingredients: ["lentils", "tomato"]
  },
  {
    id: "vegetable-rice",
    name: "Vegetable rice",
    ingredients: ["rice", "mixedVegetables"]
  },
  {
    id: "chickpea-couscous",
    name: "Chickpea couscous",
    ingredients: ["chickpeas", "couscous"]
  },
  {
    id: "potatoes-peas",
    name: "Potatoes and peas",
    ingredients: ["potatoes", "peas"]
  },
  {
    id: "vegetable-oats",
    name: "Vegetable oats",
    ingredients: ["oats", "mixedVegetables"]
  }
];

export const demoPricesCents = {
  oats: 30,
  peas: 35,
  rice: 25,
  beans: 50,
  pasta: 40,
  tomato: 30,
  lentils: 45,
  couscous: 40,
  potatoes: 35,
  chickpeas: 50,
  mixedVegetables: 60
};
"
