    {
      "path": "src/planner.js",
      "language": "javascript",
      "content": "import { mealCatalog, demoPricesCents } from './data';

export function calculatePlan(familySizeStr, budgetCentsStr) {
  // Required inputs
  if (familySizeStr === '' || budgetCentsStr === '') {
    return { error: 'Please provide both family size and budget.' };
  }

  const familySize = Number(familySizeStr);
  const budgetCents = Number(budgetCentsStr);

  // Strict integer and range validation
  if (!Number.isInteger(familySize) || familySize < 1 || familySize > 12) {
    return { error: 'Family size must be an integer between 1 and 12.' };
  }
  if (!Number.isInteger(budgetCents) || budgetCents < 0) {
    return { error: 'Budget must be an integer greater than or equal to 0.' };
  }

  let totalCostCents = 0;
  const days = [];
  const shoppingMap = {};

  mealCatalog.forEach(meal => {
    let mealCostCents = 0;
    meal.ingredients.forEach(ing => {
      const quantity = familySize;
      const price = demoPricesCents[ing] || 0;
      const lineCost = quantity * price;
      mealCostCents += lineCost;

      if (!shoppingMap[ing]) {
        shoppingMap[ing] = { quantity: 0, lineCostCents: 0 };
      }
      shoppingMap[ing].quantity += quantity;
      shoppingMap[ing].lineCostCents += lineCost;
    });

    totalCostCents += mealCostCents;
    days.push({
      mealId: meal.id,
      name: meal.name,
      costCents: mealCostCents
    });
  });

  const shoppingList = Object.keys(shoppingMap).map(ing => ({
    ingredient: ing,
    quantity: shoppingMap[ing].quantity,
    lineCostCents: shoppingMap[ing].lineCostCents
  }));

  const requiredBudgetCents = totalCostCents;

  if (totalCostCents <= budgetCents) {
    return {
      status: 'feasible',
      days,
      shoppingList,
      totalCostCents,
      requiredBudgetCents
    };
  } else {
    return {
      status: 'insufficient_budget',
      explanation: 'Budget is insufficient for the 7-day plan.',
      days: [],
      shoppingList: [],
      totalCostCents,
      requiredBudgetCents
    };
  }
}
