      "path": "src/App.jsx",
      "language": "javascript",
      "content": "import React, { useState } from 'react';
import { calculatePlan } from './planner';

function App() {
  const [familySize, setFamilySize] = useState('4');
  const [budgetCents, setBudgetCents] = useState('12000');
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);

  const handleSubmit = (e) => {
    e.preventDefault();
    setError(null);
    setResult(null);

    const plan = calculatePlan(familySize, budgetCents);
    if (plan.error) {
      setError(plan.error);
    } else {
      setResult(plan);
    }
  };

  return (
    <div className="container">
      <h1>Meal Planner Demo</h1>
      <p className="disclaimer">Demonstration prices only — not live grocery prices or nutritional advice.</p>

      <form onSubmit={handleSubmit} className="planner-form">
        <div className="form-group">
          <label htmlFor="familySize">Family Size (1-12):</label>
          <input
            type="text"
            id="familySize"
            value={familySize}
            onChange={(e) => setFamilySize(e.target.value)}
            placeholder="e.g. 4"
          />
        </div>
        <div className="form-group">
          <label htmlFor="budgetCents">Budget (in cents):</label>
          <input
            type="text"
            id="budgetCents"
            value={budgetCents}
            onChange={(e) => setBudgetCents(e.target.value)}
            placeholder="e.g. 12000"
          />
        </div>
        <button type="submit">Calculate Plan</button>
      </form>

      {error && <div className="error-message">{error}</div>}

      {result && (
        <div className="result-section">
          <h2>Status: {result.status === 'feasible' ? 'Feasible' : 'Insufficient Budget'}</h2>
          <p>Total Calculated Cost: {result.totalCostCents} cents</p>
          <p>Required Budget: {result.requiredBudgetCents} cents</p>

          {result.status === 'insufficient_budget' && (
            <div className="explanation-message">{result.explanation}</div>
          )}

          {result.status === 'feasible' && (
            <div className="plan-details">
              <h3>7-Day Meal Plan</h3>
              <ul className="days-list">
                {result.days.map((day, idx) => (
                  <li key={idx}>
                    <strong>Day {idx + 1}:</strong> {day.name} ({day.costCents} cents)
                  </li>
                ))}
              </ul>

              <h3>Shopping List</h3>
              <ul className="shopping-list">
                {result.shoppingList.map((item, idx) => (
                  <li key={idx}>
                    {item.quantity}x {item.ingredient} - {item.lineCostCents} cents
                  </li>
                ))}
              </ul>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

export default App;
