}

button {
  padding: 10px 16px;
  background-color: #2563eb;
  color: white;
  border: none;
  border-radius: 4px;
  font-size: 1rem;
  cursor: pointer;
}

button:hover {
  background-color: #1d4ed8;
}

.error-message {
  color: #b91c1c;
  background-color: #fef2f2;
  border: 1px solid #f87171;
  padding: 12px;
  border-radius: 4px;
  margin-bottom: 20px;
}

.explanation-message {
  color: #9a3412;
  background-color: #fff7ed;
  padding: 12px;
  border-radius: 4px;
  margin-top: 12px;
}

.result-section {
  border-top: 2px solid #e5e7eb;
  padding-top: 20px;
}

.days-list, .shopping-list {
  padding-left: 20px;
}
"
